<?php
require 'config/db.php';$pageTitle='Admission Form';$courses=['Artificial Intelligence','Web Development','Graphic Designing','Digital Marketing','Computer Applications','Data Science'];$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!valid_csrf())$errors[]='Security check failed. Reload and try again.';
 $fields=['full_name','father_name','dob','gender','email','phone','cnic','address','qualification','course','admission_date'];$data=[];
 foreach($fields as $f){$data[$f]=trim((string)($_POST[$f]??''));if($data[$f]==='')$errors[]='All fields are required.';}
 if(!filter_var($data['email'],FILTER_VALIDATE_EMAIL))$errors[]='Invalid email.';
 if(!preg_match('/^[0-9+()\- ]{10,20}$/',$data['phone']))$errors[]='Invalid phone.';
 if(!preg_match('/^[0-9-]{13,15}$/',$data['cnic']))$errors[]='Invalid CNIC/B-Form.';
 if(!in_array($data['gender'],['Male','Female','Other'],true))$errors[]='Invalid gender.';
 if(!in_array($data['course'],$courses,true))$errors[]='Invalid course.';
 foreach(['dob','admission_date'] as $f){$dt=DateTime::createFromFormat('!Y-m-d',$data[$f]);if(!$dt||$dt->format('Y-m-d')!==$data[$f])$errors[]='Invalid date.';}
 if(!$errors){try{$stmt=$pdo->prepare('INSERT INTO admissions (full_name,father_name,dob,gender,email,phone,cnic,address,qualification,course,admission_date) VALUES (?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute(array_values($data));$_SESSION['admission_success']=true;redirect('admission.php?success=1');}catch(PDOException $e){$errors[]='Could not save admission. Please try again.';}}
}
include 'includes/header.php';?><div class="container py-5"><div class="form-panel mx-auto"><h1 class="fw-bold">Student Admission Form</h1><p class="text-muted">Fill in the details to apply for your chosen course.</p><?php if(isset($_GET['success'])&&!empty($_SESSION['admission_success'])):unset($_SESSION['admission_success']);?><div class="alert alert-success">Admission submitted successfully!</div><?php endif;?><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',array_unique($errors)))?></div><?php endif;?><form method="post" class="row g-3 needs-validation" novalidate><input type="hidden" name="csrf" value="<?=e(csrf())?>"><?php foreach(['full_name'=>'Student Full Name','father_name'=>'Father Name','email'=>'Email Address','phone'=>'Phone Number','cnic'=>'CNIC/B-Form Number','qualification'=>'Previous Qualification'] as $key=>$label):?><div class="col-md-6"><label class="form-label"><?=e($label)?></label><input class="form-control" name="<?=$key?>" type="<?=$key==='email'?'email':'text'?>" value="<?=e($_POST[$key]??'')?>" required maxlength="150"></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Date of Birth</label><input type="date" class="form-control" name="dob" value="<?=e($_POST['dob']??'')?>" required></div><div class="col-md-6"><label class="form-label">Gender</label><select class="form-select" name="gender" required><option value="">Select gender</option><?php foreach(['Male','Female','Other'] as $v):?><option <?=($_POST['gender']??'')===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Home Address</label><textarea class="form-control" name="address" rows="2" required><?=e($_POST['address']??'')?></textarea></div><div class="col-md-6"><label class="form-label">Select Course</label><select name="course" class="form-select" required><option value="">Select course</option><?php foreach($courses as $v):?><option value="<?=e($v)?>" <?=($_POST['course']??$_GET['course']??'')===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Admission Date</label><input type="date" name="admission_date" class="form-control" value="<?=e($_POST['admission_date']??date('Y-m-d'))?>" required></div><div class="col-12"><button class="btn btn-primary btn-lg">Submit Admission</button></div></form></div></div><?php include 'includes/footer.php';?>
